122→  function normalizedPayloadRef(reference) {
123→    if (typeof reference !== "string" || reference.trim() === "") {
124→      return null;
125→    }
126→    var normalized = reference.replace(/\\/g, "/");
127→    if (normalized.charAt(0) === "/" || /^[a-zA-Z]:/.test(normalized)) {
128→      return null;
129→    }
130→    var parts = normalized.split("/");
131→    if (parts.some(function (part) { return part === "" || part === "." || part === ".."; })) {
132→      return null;
133→    }
134→    return normalized;
135→  }
