357→  function appendCitation(parent, reference, kind, validation) {
358→    var text = String(reference);
359→    var target = kind === "evidence" ? state.evidenceIndex[text] : state.policyIndex[text];
360→    var unknown = validation && (kind === "evidence"
361→      ? Array.isArray(validation.unknown_evidence_refs) && validation.unknown_evidence_refs.indexOf(text) !== -1
362→      : Array.isArray(validation.unknown_rule_ids) && validation.unknown_rule_ids.indexOf(text) !== -1);
363→    var citation;
364→    if (target && !unknown) {
365→      citation = element("a", "citation citation-" + kind, text);
366→      citation.href = "#" + target.id;
367→      if (kind === "evidence" && (target.value === null || target.value === undefined)) {
368→        citation.classList.add("citation-null");
369→      }
370→    } else {
371→      citation = element("span", "citation citation-unresolved", text);
372→      citation.title = "Citation could not be resolved in this case file.";
373→    }
374→    parent.appendChild(citation);
